INSERT INTO pages (id, slug, title, meta_description, show_in_nav, nav_order) VALUES
  (1, 'home', 'Home', 'Luxury fully-furnished apartments for extended stays in the Pacific Northwest — for business travelers, travel nurses, relocations and more.', 1, 0),
  (2, 'about', 'About', 'About 5R Suites — a veteran-owned provider of luxury fully-furnished apartments for extended stays.', 1, 10),
  (3, 'register-property', 'Register Property', 'List your property with 5R Suites and receive a free short-term rental market report.', 1, 20),
  (4, 'partners', 'Partners', 'Partner with 5R Suites — guaranteed monthly income, committed insurance and no vacancies.', 1, 30),
  (5, 'faq', 'FAQ', 'Frequently asked questions about booking a 5R Suites apartment and partnering with 5R Suites.', 1, 40),
  (6, 'contact', 'Contact', 'Contact 5R Suites — Tacoma, Redmond and Seattle, WA. Phone 360-320-6166.', 1, 50);
INSERT INTO sections (page_id, position, type, data) VALUES
  (1, 0, 'hero', json('{"variant": "full", "eyebrow": "4 DAYS. 30 DAYS. 450 DAYS. YOUR CHOICE.", "heading": "Design Your Stay", "subheading": "5R Suites offers modern and elegantly designed accommodations for extended stays. Business and leisure travellers enjoy our fully equipped and furnished Suites that have been hand-picked from premium communities for quality and security. Experience the city as a local while enjoying the comforts of home. We work together to make your most valuable resources feel right at home.", "image": null, "cta_label": "Book Now", "cta_url": "https://5rsuites.holidayfuture.com", "secondary_label": "Learn More", "secondary_url": "/about"}')),
  (1, 1, 'traveler_grid', json('{"heading": "Ideal Choice For", "intro": "", "background": "white", "items": [{"title": "Vacation Travelers", "description": "", "image": null}, {"title": "Travel Nurses", "description": "", "image": null}, {"title": "Corporate Travelers", "description": "", "image": null}, {"title": "Military Travelers", "description": "", "image": null}, {"title": "Insurance", "description": "", "image": null}, {"title": "Relocations", "description": "", "image": null}]}')),
  (1, 2, 'cta_banner', json('{"heading": "PNW", "body": "Pacific Northwest", "button_label": "Book Now", "button_url": "https://5rsuites.holidayfuture.com", "tone": "photo", "image": null, "size": "large"}')),
  (1, 3, 'rich_text', json('{"heading": "Home Living With Apartment Amenities", "body": "Maximize your experience at 5R Suites by utilizing your building’s amenities: pools, spas, fitness centres/gyms, conference rooms, game rooms, clubhouses, and more. No more over-crowded jacuzzis or waiting to use the treadmill. Use the amenities like any resident - because you are one!", "image": null, "image_side": "right", "background": "white", "align": "left", "button_label": "Register Property", "button_url": "/register-property"}')),
  (1, 4, 'quote', json('{"quote": "There’s nothing quite like a change in perspective.", "attribution": "", "role": "", "tone": "brown"}')),
  (1, 5, 'amenity_grid', json('{"heading": "Thoughtfully Designed, Private Apartments", "intro": "Each Suite is designed for the business and leisure traveler alike; always with your lifestyle in mind. Enjoy the benefits of a fully equipped kitchen, washer + dryer in-unit, ample privacy, and space often 2X the size of a traditional hotel room; 5R Suites is the perfect alternative to an overpriced hotel room.", "items": [{"icon": "workspace", "label": "Tastefully Furnished", "description": ""}, {"icon": "wifi", "label": "In-Unit Workspace + WiFi", "description": ""}, {"icon": "calendar", "label": "Contemporary Design", "description": ""}, {"icon": "linens", "label": "Luxury Bath Amenities", "description": ""}, {"icon": "kitchen", "label": "Fully Equipped Kitchen", "description": ""}, {"icon": "laundry", "label": "In-Unit Washer + Dryer", "description": ""}, {"icon": "parking", "label": "Parking Available", "description": ""}, {"icon": "support", "label": "24-Hour Virtual Concierge", "description": ""}, {"icon": "utilities", "label": "Air Conditioning + Heating", "description": ""}, {"icon": "security", "label": "Seamless Check-In Experience", "description": ""}, {"icon": "tv", "label": "TV + Free Streaming (Netflix, Hulu, etc.)", "description": ""}, {"icon": "cleaning", "label": "Housekeeping Available", "description": ""}]}')),
  (1, 6, 'cta_banner', json('{"heading": "Building, Owners & Developers", "body": "We offer buildings an opportunity to diversify inventory and maximize profitability using our streamlined processes and technology.", "button_label": "Partner With Us", "button_url": "/partners", "tone": "gold", "image": null, "size": "normal"}')),
  (1, 7, 'contact_strip', json('{"heading": "Contact Info", "address": "Tacoma, WA, US · Redmond, WA, US · Seattle, WA, US", "phone": "360-320-6166", "email": "info@5rsuites.com", "hours": "", "style": "brown", "map_query": "Tacoma, WA"}')),
  (2, 0, 'hero', json('{"variant": "title", "eyebrow": "", "heading": "About Us", "subheading": "", "image": null, "cta_label": "", "cta_url": "", "secondary_label": "", "secondary_url": ""}')),
  (2, 1, 'rich_text', json('{"heading": "Redefining Hospitality.", "body": "5R Suites offers modern and elegantly designed accommodations for extended stays. Business and leisure travellers enjoy our fully equipped and furnished Suites that have been hand-picked from premium communities for quality and security. Experience the city as a local while enjoying the comforts of home. We work together to make your most valuable resources feel right at home. At 5R Suites, we’re on a mission to set the standard of excellence in travel solutions and guest experiences.", "image": null, "image_side": "right", "background": "white", "align": "center", "button_label": "Book Now", "button_url": "https://5rsuites.holidayfuture.com"}')),
  (2, 2, 'rich_text', json('{"heading": "Our Mission", "body": "Our Mission is to provide a premium stress-free experience for the travelling professional needing flexible term stays where every detail matters. We are dedicated to delivering remarkable service through accessible, streamlined booking and check-in processes, elegantly fully-furnished units, and around-the-clock customer service.", "image": null, "image_side": "right", "background": "white", "align": "left", "button_label": "Register Property", "button_url": "/register-property"}')),
  (2, 3, 'rich_text', json('{"heading": "Our Start", "body": "After transitioning out of the army after 5 years of service, our CEO and Founder, Jeff Kim began to manage a small handful of apartments via Airbnb. He personally furnished each unit, moved in furniture, greeted guests with wine and walkthroughs and started to picture a new standard of corporate travel.\n\nOver the next few years, Jeff transitioned from Airbnb to creating 5R Suites to provide travelers with more value, flexibility, and security. Through developing lasting relationships with guests, building managers and property owners, and employees, 5R Suites has grown exponentially since that first unit set-up in 2017.", "image": null, "image_side": "right", "background": "gold", "align": "center", "button_label": "Become Our Partner", "button_url": "/partners"}')),
  (2, 4, 'rich_text', json('{"heading": "5R Suites Now", "body": "5R Suites is Tacoma-based with additional locations in Redmond, WA and San Mateo, CA.\n\n- 100,000+ nights booked\n- Average 4.9-star review\n- Renovating 10 unit building, estimated opening in 2022", "image": null, "image_side": "right", "background": "white", "align": "left", "button_label": "Contact Us", "button_url": "/contact"}')),
  (2, 5, 'rich_text', json('{"heading": "Careers", "body": "We are always on the lookout for reliable, motivated individuals to join the 5R Suites team.\n\n### Work with us\nAre you interested in property management? Have experience in real estate, customer service, hospitality, or sales? Handy? Self-starter? Looking for a flexible schedule? Let us know! We will get back to you with any opportunities.\n\n### DOD paid internships\nAs a veteran-owned company, we offer exclusive paid internship opportunities through the DOD SkillBridge and Hiring Our Heroes programs. Message us to learn more.\n\n### Partner with us\nBuilding owner or developer? For information on partnerships check out [our Partners page](/partners).\n\nFill out the form below or email us directly at [Careers@5RSuites.com](mailto:Careers@5RSuites.com).", "image": null, "image_side": "right", "background": "white", "align": "left", "button_label": "", "button_url": ""}')),
  (2, 6, 'form', json('{"form": "careers", "heading": "Fill The Career Form", "intro": ""}')),
  (3, 0, 'hero', json('{"variant": "title", "eyebrow": "", "heading": "Register Property", "subheading": "", "image": null, "cta_label": "", "cta_url": "", "secondary_label": "", "secondary_url": ""}')),
  (3, 1, 'form', json('{"form": "register_property", "heading": "Landlord Information", "intro": ""}')),
  (4, 0, 'hero', json('{"variant": "title", "eyebrow": "", "heading": "Partner With Us", "subheading": "", "image": null, "cta_label": "", "cta_url": "", "secondary_label": "", "secondary_url": ""}')),
  (4, 1, 'rich_text', json('{"heading": "Your Dream Tenant", "body": "- **Proven Payments:** Guaranteed monthly income; on time, every time. Incredibly strong balance sheet and large operating account. NO deferments or late payments during COVID-19.\n- **Committed Insurance:** All 5R Suites units are covered through commercial-grade $2 million premises liability and $6 million excess liability coverage.\n- **No Vacancies:** Immediately lease-up units. Say goodbye to vacancies, turnover, lease commissions, and credit loss.", "image": null, "image_side": "right", "background": "white", "align": "left", "button_label": "Contact Us", "button_url": "/contact"}')),
  (4, 2, 'traveler_grid', json('{"heading": "", "intro": "", "background": "cream", "items": [{"title": "Tech Enabled", "description": "We fund connected home improvements. All of 5R Suites technology must enhance both the guest experience and our ability to monitor and control safety and security. From noise monitoring to home automation, we combine technology with hospitality.", "image": null}, {"title": "Serving the Community", "description": "Our Suites cater to professional clientele consisting of: travel nurses, corporate sponsored workers, university professors, and government/military personnel on official orders.", "image": null}, {"title": "Dedicated to Safety", "description": "5R Suites utilizes a strict verification process and fraud prevention system to ensure all guests are fully vetted. We also cross-reference guests across industry blacklists and use machine-learning software to enhance our background checks.", "image": null}]}')),
  (4, 3, 'quote', json('{"quote": "5R Suites is nothing short of excellent. From on-time payments to being completely accommodating and friendly all around, it is a pleasure working with them!", "attribution": "Napoleon Apartments", "role": "", "tone": "white"}')),
  (4, 4, 'image_gallery', json('{"heading": "Our Partners", "variant": "logo_strip", "images": []}')),
  (5, 0, 'hero', json('{"variant": "title", "eyebrow": "", "heading": "Frequently Asked Question", "subheading": "", "image": null, "cta_label": "", "cta_url": "", "secondary_label": "", "secondary_url": ""}')),
  (5, 1, 'faq_list', json('{"heading": "FAQs - Corporate Suites Nationwide", "subheading": "", "category": "", "limit": 0}')),
  (6, 0, 'hero', json('{"variant": "title", "eyebrow": "", "heading": "Get In Touch", "subheading": "", "image": null, "cta_label": "", "cta_url": "", "secondary_label": "", "secondary_url": ""}')),
  (6, 1, 'contact_strip', json('{"heading": "Contact Info", "address": "Tacoma, WA, US · Redmond, WA, US · Seattle, WA, US", "phone": "360-320-6166", "email": "info@5rsuites.com", "hours": "", "style": "white", "map_query": "Tacoma, WA"}')),
  (6, 2, 'form', json('{"form": "contact", "heading": "Contact Us", "intro": ""}'));
